(()=>{
const F=window.AuroraFinance,q=s=>document.querySelector(s),brl=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),n=id=>q('#'+id).hasAttribute('data-money')?window.AuroraMoney.parse(q('#'+id).value):Number(q('#'+id).value),val=id=>q('#'+id).value;
const source='https://www.gov.br/cidades/pt-br/acesso-a-informacao/acoes-e-programas/habitacao/programa-minha-casa-minha-vida/mcmv-fgts',classSource='https://www.gov.br/cidades/pt-br/acesso-a-informacao/acoes-e-programas/habitacao/programa-minha-casa-minha-vida/minha-casa-minha-vida-classe-media/minha-casa-minha-vida-classe-media-1';
const numeric=(id,label,value,min=0,max=1e8,step='.01')=>{const currency=label.includes('R$');return `<label>${label}<input id="${id}" type="${currency?'text':'number'}" ${currency?'data-money inputmode="decimal" data-min="'+min+'" data-max="'+max+'"':''} value="${value}" min="${min}" max="${max}" step="${step}" required></label>`;};
const now=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit'}).format(new Date()),mi=F.monthIndex(now),start=F.monthString(mi+1),end=F.monthString(mi+24);
const dialog=document.createElement('section');dialog.id='financeDialog';dialog.hidden=true;dialog.setAttribute('aria-labelledby','financeTitle');dialog.innerHTML=`<div class="finance-head"><div><p class="eyebrow">COMPRA PLANEJADA</p><h2 id="financeTitle">Financiamento & entrada</h2><p id="financeUnit"></p></div><button id="closeFinance" aria-label="Voltar para escolher apartamento">↑ Escolher apartamento</button></div><div class="finance-intro">Estimativa independente, sem conexão com a Caixa e sem aprovação de crédito. Valores iniciais são exemplos. Dados ficam apenas nesta sessão.</div><div class="finance-layout"><div class="finance-inputs"><section><h3><span>01</span> Estime o financiamento</h3><p class="muted">Imóvel novo/em construção em São Paulo (capital). Regras consultadas em 06/10/2026.</p><form id="loanForm"><label>Modo de cálculo<select id="loanMode"><option value="quick">Rápido · referência da calculadora Caixa</option><option value="custom">Personalizado · premissas editáveis</option></select></label><p id="quickNote" class="muted">Modelo da calculadora rápida consultado em 06/10/2026: usa renda, nascimento e preço; escolhe taxa, sistema e encargos automaticamente. Não considera dívidas ou FGTS; o subsídio abaixo é uma estimativa adicional nossa, abatida somente da entrada. É uma reprodução independente, sem conexão com o banco.</p><div class="form-grid"><label>Data de nascimento do mais velho<input id="loanBirth" type="date" value="1991-01-01" required></label>${numeric('quickPrice','Valor do imóvel para simular (R$)',500000,100)}${numeric('loanIncome','Renda familiar bruta (R$/mês)',10000,1,1000000)}${numeric('loanDebts','Outras parcelas e compromissos (R$/mês)',0,0,1000000)}<label>Linha de crédito<select id="loanProduct"><option value="classe">MCMV Classe Média · até R$ 600 mil</option><option value="faixa">MCMV · faixa pela renda</option></select></label><label>Sistema de amortização<select id="loanSystem"><option value="SAC">SAC · prestação decrescente</option><option value="PRICE">Price · prestação-base constante</option></select></label><label>Início previsto do financiamento<input id="loanBegin" type="date" value="${now}-01" required></label>${numeric('loanMonths','Prazo desejado (meses)',420,1,420,1)}${numeric('loanQuota','Cota de financiamento simulada (%)',80,1,90)}${numeric('loanCosts','Reserva para seguros/tarifas (R$/mês)',150,0,100000)}${numeric('loanFgts','FGTS a utilizar (R$)',0)}${numeric('loanSubsidy','Subsídio aproximado / editável (R$)',0,0,55000)}<label class="checkline"><input id="subsidyAuto" type="checkbox" checked>Estimar subsídio automaticamente</label><label class="checkline"><input id="subsidySingle" type="checkbox">Família unipessoal (sem dependentes)</label><p id="subsidyNote" class="muted"></p><label class="checkline"><input id="loanCotista" type="checkbox" checked>Cotista do FGTS conforme os critérios do banco</label><label class="checkline"><input id="loanProperty" type="checkbox">Já possui imóvel ou financiamento habitacional</label></div><p id="customNote" class="muted">A reserva de R$ 150 é uma hipótese editável, não uma cotação de seguros. A cota de 80% é um parâmetro inicial; o banco pode financiar menos. O subsídio pode ser estimado ou editado.</p></form></section><section><h3><span>02</span> Distribua sua entrada</h3><form id="planForm"><div class="form-grid"><label>Valor a planejar<select id="entryMode"><option value="estimate">Entrada desta simulação</option><option value="manual">Valor informado pela construtora</option></select></label>${numeric('manualEntry','Entrada a planejar (R$)',0)}<label>Mês da contratação<input id="planContract" type="month" value="${now}" required></label><label>Primeira parcela mensal<input id="planStart" type="month" value="${start}" required></label><label>Última mensal / chaves<input id="planEnd" type="month" value="${end}" required></label>${numeric('planSignal','Sinal na contratação (R$)',10000)}<div class="monthly-control">${numeric('planMonthly','Parcela mensal que pretende pagar (R$)',2000)}<label class="monthly-auto"><input id="autoMonthly" type="checkbox">Calcular parcela mensal automaticamente</label><small class="muted">Desconta sinal, extras e chaves da entrada e divide o saldo entre as mensais. Centavos restantes vão na última parcela.</small></div>${numeric('planCapacity','Orçamento mensal para a entrada (R$)',2500)}${numeric('planKeys','Pagamento adicional nas chaves (R$)',15000)}${numeric('planCorrection','Correção anual projetada (%)',0,0,30)}</div><p class="muted">Você pode digitar as datas ou usar o ícone do calendário. Mensais incluem o primeiro e o último mês. Sinal, extras e chaves são adicionais às mensais. A data de chaves é uma hipótese editável, não a data de lançamento.</p><h4>Pagamentos extras</h4><div id="extraRows"></div><button type="button" id="addExtra">Adicionar anual, semestral ou avulsa</button><p class="muted">Extras se repetem a partir do primeiro vencimento informado até as chaves. </p></form></section></div><aside class="finance-results"><div id="loanResult" aria-live="polite"></div><div id="planResult" aria-live="polite"></div></aside></div><section class="finance-calendar"><div class="calendar-head"><div><h3>Pagamentos mensais da entrada</h3><p class="muted">Valores em R$. Desembolsos planejados: sinal, mensal, extras, chaves e correção. Não são pagamentos já realizados.</p></div><div class="chart-nav"><button id="chartPrev" aria-label="Voltar um mês">←</button><span id="chartRange" aria-live="polite"></span><button id="chartNext" aria-label="Avançar um mês">→</button></div></div><div id="paymentChart" role="img" aria-label="Gráfico dos pagamentos planejados por mês"></div><div id="chartValues" class="chart-values"></div><div class="calendar-head"><div><h3>Calendário da entrada</h3><p id="calendarNote" class="muted"></p></div><button id="downloadPlan">Baixar planejamento CSV</button></div><div class="table-scroll"><table><thead><tr><th>Mês</th><th>Sinal</th><th>Mensal</th><th>Extras</th><th>Chaves</th><th>Correção</th><th>Total do mês</th><th>Acumulado</th></tr></thead><tbody id="calendarRows"></tbody></table></div></section><details class="finance-method"><summary>Premissas, limites e fontes do cálculo</summary><p><b>Modo rápido:</b> implementação independente dos parâmetros públicos da <a href="https://simuladorhabitacao.caixa.gov.br/calculadora" target="_blank" rel="noreferrer">calculadora rápida da Caixa</a>, consultada em 06/10/2026. Seleção de taxa pela maior faixa entre renda e preço, cota de 80%, prazo de até 420 meses e término até 80 anos e 6 meses. Tarifa mensal de R$ 25, MIP por idade e DFI de 0,0066% ao mês. Ao limitar o financiamento pela renda, a calculadora usa no DFI um valor de referência reduzido (financiamento ÷ 80%), e este modo reproduz essa simplificação. Encargos constantes e despesas de aquisição estimadas em 5% não representam cotação ou tributo efetivo. Acima dos limites do MCMV, a calculadora rápida utiliza outras faixas de crédito habitacional. O resultado não confirma elegibilidade. As regras podem mudar; valide no banco.</p><p><b>Subsídio aproximado:</b> referência dos arts. 53–54 da <a href="https://www.gov.br/cidades/pt-br/acesso-a-informacao/institucional/base-juridica/instrucoes-normativas/IN_48_de_19.12.22__compilada_em_16.12.2025_rev1.pdf" target="_blank" rel="noreferrer">IN 48 compilada em dezembro/2025</a>: hipótese de apartamento em construção, São Paulo capital, área coberta de 43 m² e cotista no modo rápido. Usa fator de renda, demanda, área e população; redução para família unipessoal. A estimativa automática desta referência limita-se à renda de R$ 4.000 e imóvel de até R$ 275 mil; fora desse cenário, começa em zero e permite valor validado manualmente. Não confirma elegibilidade nem substitui a atualização normativa e análise do banco.</p><p><b>Modo personalizado:</b> as premissas abaixo aplicam-se aos campos editáveis.</p><p>Renda disponível estimada: 30% da renda bruta, menos os compromissos declarados e a reserva de seguros/tarifas. Taxa nominal anual dividida por 12. Financiamento limitado pela renda, pela cota e pelo preço menos FGTS e subsídio. SAC considera a primeira prestação, a maior; Price usa a prestação-base constante. Seguros reais podem variar por idade, saldo e composição de renda.</p><p>Prazo de até 420 meses, limitado pela hipótese de idade de 80 anos e 6 meses ao término. A idade é calculada pela data de nascimento; no modo personalizado, considera o início previsto do financiamento. Não há cálculo de CET, TR futura, juros de evolução de obra, ITBI ou cartório. A prestação apresentada é a da fase de amortização, não o encargo durante a construção.</p><p>Entrada e financiamento são fluxos distintos. O calendário não soma parcelas do banco aos pagamentos à construtora. Se houver sobreposição contratual, ela deve ser analisada à parte. Correção da entrada é uma projeção uniforme sobre cada pagamento desde o mês da contratação; não é previsão de INCC nem reprodução de um contrato. O saldo a distribuir é calculado em reais do mês da contratação, sem misturar correção com entrada-base.</p><p>Na Classe Média, o limite normativo para imóvel novo é 90% no SAC e 80% no Price; a cota efetiva depende do banco. Nas demais faixas, este estudo usa no máximo 80% como premissa conservadora a confirmar. Renda e preço não bastam para confirmar elegibilidade, uso do FGTS ou subsídio. A modalidade Classe Média pode ser testada separadamente quando o preço superar o teto da faixa pela renda.</p><p><a href="${source}" target="_blank" rel="noreferrer">Faixas, taxas e tetos · Ministério das Cidades</a> · <a href="${classSource}" target="_blank" rel="noreferrer">Regras da Classe Média</a> · <a href="https://www.caixa.gov.br/voce/habitacao/lote-urbanizado/Paginas/default.aspx" target="_blank" rel="noreferrer">Referências de idade e comprometimento · Caixa</a> · <a href="https://simuladorhabitacao.caixa.gov.br/home" target="_blank" rel="noreferrer">Simulador oficial da Caixa</a></p></details>`;
q('main').append(dialog);let unit=null,loan=null,plan=null,extraId=0,chartOffset=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function card(label,value){return `<div class="result-value"><span>${label}</span><strong>${value}</strong></div>`;}
function params(){return {price:unit.preco,income:n('loanIncome'),debts:n('loanDebts'),costs:n('loanCosts'),age:F.ageAt(val('loanBirth'),val('loanBegin')),months:n('loanMonths'),quota:n('loanQuota'),fgts:n('loanFgts'),subsidy:n('loanSubsidy'),product:val('loanProduct'),system:val('loanSystem'),cotista:q('#loanCotista').checked,hasProperty:q('#loanProperty').checked};}
function update(){if(!unit)return;const quick=val('loanMode')==='quick';for(const el of q('#loanForm').querySelectorAll('input,select')){const visible=['loanMode','loanIncome','loanBirth','loanSubsidy','subsidyAuto','subsidySingle'].includes(el.id)||(quick?['loanBirth','quickPrice'].includes(el.id):!['loanBirth','quickPrice'].includes(el.id));el.disabled=!visible;el.closest('label').style.display=visible?'':'none';}q('#quickNote').hidden=!quick;q('#customNote').hidden=quick;const subsidy=F.subsidyEstimate({income:n('loanIncome'),price:quick?n('quickPrice'):unit.preco,classe:!quick&&val('loanProduct')==='classe',hasProperty:!quick&&q('#loanProperty').checked,cotista:quick?true:q('#loanCotista').checked,single:q('#subsidySingle').checked,area:43});if(q('#subsidyAuto').checked)q('#loanSubsidy').value=window.AuroraMoney.format(subsidy.value);q('#subsidyNote').textContent=(q('#subsidyAuto').checked?subsidy.reason:'Valor alterado manualmente. '+subsidy.reason+' ')+ ' Estimativa não aprovada; editar o valor desliga o automático.';loan=null;plan=null;q('#downloadPlan').disabled=true;q('#manualEntry').disabled=val('entryMode')!=='manual';q('#planMonthly').readOnly=q('#autoMonthly').checked;window.AuroraMoney.refresh();q('#calendarRows').innerHTML='';q('#paymentChart').innerHTML='';q('#chartValues').innerHTML='';q('#chartRange').textContent='';q('#chartPrev').disabled=true;q('#chartNext').disabled=true;q('#calendarNote').textContent='';try{if(!q('#loanForm').checkValidity())throw Error('Preencha os campos de financiamento com valores válidos.');loan=quick?F.quickFinancing({income:n('loanIncome'),price:n('quickPrice'),birth:val('loanBirth')}):F.financing(params());if(loan.valid&&quick){loan.grossCash=loan.cash;if(n('loanSubsidy')>loan.cash)throw Error('Subsídio não pode superar a entrada total.');loan.cash=Math.round((loan.cash-n('loanSubsidy'))*100)/100;loan.subsidy=n('loanSubsidy');}if(!loan.valid)q('#loanResult').innerHTML=`<div class="result-box warning"><h3>Revise o enquadramento</h3>${loan.errors.map(e=>`<p>${esc(e)}</p>`).join('')}<p class="muted">Você ainda pode planejar uma entrada informada pela construtora.</p></div>`;else q('#loanResult').innerHTML=`<div class="result-box"><p class="eyebrow">${loan.quick?loan.label:loan.classe?'MCMV CLASSE MÉDIA':'MCMV · FAIXA '+loan.faixa}</p><h3>Estimativa para sua renda</h3>${card('Financiamento estimado',brl(loan.principal))}${card('Entrada em recursos próprios',brl(loan.cash))}<div class="result-pair">${card('Primeira prestação',brl(loan.first))}${card('Última prestação',brl(loan.last))}</div><p>${loan.months} meses · ${loan.annual.toLocaleString('pt-BR')}% a.a. ${loan.quick?'efetiva':'nominal'} · ${loan.quick?loan.system:val('loanSystem')}</p>${loan.quick?`<p>Imóvel simulado: <b>${brl(loan.price)}</b></p><p class="muted">Encargos mensais estimados: ${brl(loan.costs)} — tarifa ${brl(loan.tac)}, MIP ${brl(loan.mip)} e DFI ${brl(loan.dfi)}. Mantidos constantes neste modelo simplificado.</p>${card('ITBI e outras despesas · hipótese de 5%',brl(loan.expenses))}<p class="muted">Despesas de aquisição ficam fora da entrada. Subsídio considerado na entrada: ${brl(loan.subsidy)}. Para usar FGTS, selecione o modo personalizado. Editar o preço aqui não altera o apartamento.</p>`:`<p class="muted">FGTS: ${brl(n('loanFgts'))} · subsídio informado: ${brl(n('loanSubsidy'))}. Não entram novamente no planejamento da entrada própria.</p>`}${loan.warnings.map(e=>`<p class="warning-text">${esc(e)}</p>`).join('')}<button id="downloadLoan">Baixar parcelas do financiamento</button><p class="muted">Não representa aprovação. Seguros/tarifas são estimativas do modo escolhido; TR e evolução de obra não estão incluídas.</p></div>`;}catch(e){loan=null;q('#loanResult').innerHTML=`<div class="result-box warning">${esc(e.message)}</div>`;}
q('#downloadLoan')?.addEventListener('click',()=>saveCSV('aurora-financiamento.csv',[['Apartamento',unit.unidade],['Preço',loan.quick?loan.price:unit.preco],['Renda',n('loanIncome')],['Subsidio_estimado_ou_informado',n('loanSubsidy')],[loan.quick?'Taxa efetiva anual':'Taxa nominal anual',loan.annual],['Sistema',loan.quick?loan.system:val('loanSystem')],['Encargos mensais estimados',loan.quick?loan.costs:n('loanCosts')],['Premissas','Sem TR futura, CET ou juros de obra; estimativa sem aprovação'],['Mes','Amortizacao','Juros','Prestacao_com_reserva','Saldo'],...loan.rows.map(r=>[r.month,r.principal,r.interest,r.payment,r.balance])]));
if(val('entryMode')==='estimate'){q('#manualEntry').value=loan?.valid?window.AuroraMoney.format(loan.cash):'';q('#manualEntry').placeholder=loan?.valid?'':'Conclua a simulação';q('#manualEntry').setCustomValidity('');}
try{if(!q('#planForm').checkValidity())throw Error('Preencha os campos de entrada com valores e datas válidos.');if(val('entryMode')==='estimate'&&!loan?.valid)throw Error('Conclua uma simulação válida ou escolha “Valor informado pela construtora”.');const target=val('entryMode')==='manual'?n('manualEntry'):loan.cash;plan=F.planning({target,contract:val('planContract'),start:val('planStart'),end:val('planEnd'),signal:n('planSignal'),monthly:q('#autoMonthly').checked?0:n('planMonthly'),autoMonthly:q('#autoMonthly').checked,capacity:n('planCapacity'),keys:n('planKeys'),correction:n('planCorrection'),extras:[...q('#extraRows').children].map(r=>({date:r.querySelector('[data-date]').value,amount:window.AuroraMoney.parse(r.querySelector('[data-amount]').value),every:Number(r.querySelector('[data-every]').value)}))});if(q('#autoMonthly').checked)q('#planMonthly').value=window.AuroraMoney.format(plan.monthly);const over=plan.gap<-.005; q('#planResult').innerHTML=`<div class="result-box ${plan.gap>.005?'pending':'complete'}"><p class="eyebrow">PLANEJAMENTO DA ENTRADA</p>${card('Entrada própria a distribuir',brl(target))}${card(over?'Planejado a mais':plan.gap>.005?'Ainda falta distribuir':'Entrada-base distribuída',brl(Math.abs(plan.gap)))}<progress max="${Math.max(target,1)}" value="${Math.min(plan.baseTotal,target)}"></progress><p>${brl(plan.baseTotal)} planejados em valores-base.</p><p><b>${plan.count} parcelas mensais</b></p>${q('#autoMonthly').checked?`<p class="muted">Cálculo automático: mensal-base de ${brl(plan.monthly)}${plan.lastMonthly!==plan.monthly?`, última mensal-base de ${brl(plan.lastMonthly)}`:''}. Extras e correção são somados no calendário.</p>`:''}${plan.gap>.005?`<p>Para completar mantendo os extras, a mensal-base seria <b>${brl(plan.monthlySuggestion)}</b>, com ajuste de centavos na última parcela.</p>`:''}${n('planCorrection')>0?`<p>Total de desembolsos projetados: <b>${brl(plan.total)}</b>, incluindo ${brl(plan.correction)} de correção estimada sobre o que foi planejado.</p>`:'<p class="muted">Valores sem correção contratual.</p>'}${over?'<p class="warning-text">Reduza os pagamentos planejados para evitar exceder a entrada.</p>':''}</div>`;
q('#calendarRows').innerHTML=plan.rows.map(r=>`<tr ><th scope="row">${r.date.slice(5)}/${r.date.slice(0,4)}</th>${['signal','monthly','extras','keys','correction','total','cumulative'].map(k=>`<td>${brl(r[k])}</td>`).join('')}</tr>`).join('');q('#calendarNote').textContent=`${plan.count} mensais de ${val('planStart').split('-').reverse().join('/')} a ${val('planEnd').split('-').reverse().join('/')}. Valores em reais; pagamentos extras são somados, não substituem a mensal.`;q('#downloadPlan').disabled=false;drawChart();}catch(e){q('#planResult').innerHTML=`<div class="result-box warning">${esc(e.message)}</div>`;}}
function saveCSV(name,rows){const text='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
q('#downloadPlan').onclick=()=>{if(!plan)return;saveCSV('aurora-planejamento-entrada.csv',[['Apartamento',unit.unidade],['Preço',val('entryMode')==='estimate'&&loan?.quick?loan.price:unit.preco],['Entrada_base',val('entryMode')==='manual'?n('manualEntry'):loan.cash],['Origem',val('entryMode')==='manual'?'Informada pela construtora':'Estimativa independente MCMV'],['Subsidio_estimado_ou_informado',n('loanSubsidy')],['Mensal_automatica',q('#autoMonthly').checked?'Sim':'Não'],['Saldo_base_a_distribuir',plan.gap],['Correcao_anual_projetada_percentual',n('planCorrection')],['Orcamento_mensal',n('planCapacity')],['Premissas','Sem aprovação de crédito; correção hipotética; não inclui encargos de obra'],['Mes','Sinal','Mensal','Extras','Chaves','Correcao','Total','Acumulado'],...plan.rows.map(r=>[r.date,r.signal,r.monthly,r.extras,r.keys,r.correction,r.total,r.cumulative])]);};
q('#addExtra').onclick=()=>{const row=document.createElement('div');row.className='extra-row';const id=++extraId;row.innerHTML=`<label>Primeiro vencimento<input data-date type="month" value="${val('planStart')}" required></label><label>Valor (R$)<input data-amount data-money data-min="0" data-max="100000000" inputmode="decimal" type="text" value="R$ 10.000,00" required></label><label>Frequência<select data-every><option value="0">Uma vez</option><option value="6">Semestral</option><option value="12">Anual</option></select></label><button type="button" aria-label="Remover pagamento extra ${id}">×</button>`;row.querySelector('button').onclick=()=>{row.remove();update()};q('#extraRows').append(row);update();};
for(const id of ['loanForm','planForm']){q('#'+id).addEventListener('input',e=>{if(e.target.id==='loanSubsidy')q('#subsidyAuto').checked=false;update();});q('#'+id).addEventListener('change',update);q('#'+id).onsubmit=e=>e.preventDefault();}

function drawChart(){if(!plan)return;chartOffset=Math.max(0,Math.min(chartOffset,Math.max(0,plan.rows.length-12)));const rows=plan.rows.slice(chartOffset,chartOffset+12),max=Math.max(1,...rows.map(r=>r.total)),x=i=>52+i*99,y=v=>205-v/max*155;const points=rows.map((r,i)=>x(i)+','+y(r.total)).join(' ');q('#paymentChart').innerHTML='<svg viewBox="0 0 1200 250" aria-hidden="true"><line x1="35" y1="205" x2="1170" y2="205" stroke="#bccdd6"/><polyline points="'+points+'" fill="none" stroke="#377d56" stroke-width="3"/>'+rows.map((r,i)=>'<circle cx="'+x(i)+'" cy="'+y(r.total)+'" r="5" fill="#377d56"/><text x="'+x(i)+'" y="'+(y(r.total)-14)+'" text-anchor="middle" font-size="12" font-weight="600" fill="#182a37">'+r.total.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+'</text><text x="'+x(i)+'" y="232" text-anchor="middle" font-size="12" fill="#334c5b">'+r.date.slice(5)+'/'+r.date.slice(2,4)+'</text>').join('')+'</svg>';q('#chartValues').innerHTML='';q('#paymentChart').setAttribute('aria-label',rows.map(r=>r.date+': '+brl(r.total)).join('; '));q('#chartRange').textContent=rows[0].date.split('-').reverse().join('/')+' – '+rows.at(-1).date.split('-').reverse().join('/');q('#chartPrev').disabled=chartOffset===0;q('#chartNext').disabled=chartOffset+12>=plan.rows.length;}
q('#chartPrev').onclick=()=>{chartOffset=Math.max(0,chartOffset-1);drawChart();};q('#chartNext').onclick=()=>{chartOffset=Math.max(0,Math.min(plan.rows.length-12,chartOffset+1));drawChart();};
q('#closeFinance').onclick=()=>q('#unitGrid').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});function sync(u){unit={...u};q('#quickPrice').value=u.preco;q('#financeUnit').textContent=`Apartamento ${u.unidade} · ${u.area} m² · ${brl(u.preco)} · ${u.status}`;update();}window.syncAuroraFinance=u=>{if(unit)sync(u);};window.openAuroraFinance=u=>{dialog.hidden=false;sync(u);dialog.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});};
})();



